    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # A partial solid bar is completed in the color used for continuation.
    full_lines = {
        row[0] for row in grid
        if row[0] != bg and all(v == row[0] for v in row)
    }
    for r, row in enumerate(grid):
        color = row[0]
        if color == bg or color not in full_lines:
            continue
        n = 0
        while n < w and row[n] == color:
            n += 1
        if 0 < n < w and all(v == bg for v in row[n:]):
            for c in range(n, w):
                out[r][c] = 1

    # When an alternating motif is present, continue it after a shared
    # endpoint in an adjacent pair of rows.
    for color in set(v for row in grid for v in row if v != bg):
        has_alternation = any(
            any(all(row[start + 2 * k] == color for k in range(4))
                for start in range(w - 6))
            for row in grid
        )
        if not has_alternation:
            continue

        for r in range(h - 1):
            shared = [c for c in range(w)
                      if grid[r][c] == color and grid[r + 1][c] == color]
            if len(shared) < 3:
                continue
            endpoint = max(shared)
            for c in range(endpoint + 2, w, 2):
                if grid[r][c] == bg and grid[r + 1][c] == bg:
                    out[r][c] = 1
                    out[r + 1][c] = 1

    return out
